{"thought": "Handover notes only cover rest_violations (not my ticket). Spec is fully clear from the stub. Let me implement merge_intervals: sort by start, drop empty (start==end), raise ValueError on start>end, merge overlaps/touching.", "action": {"tool": "edit_file", "args": {"path": "src/slotplan/merge_intervals.py", "old": "    raise NotImplementedError", "new": "    if intervals is None:
        raise TypeError("intervals must be an iterable of (start, end) tuples")

    cleaned: List[Tuple[int, int]] = []
    for item in intervals:
        if len(item) != 2:
            raise ValueError(f"interval must be a (start, end) pair, got {item!r}")
        start, end = item
        if start > end:
            raise ValueError(f"invalid interval: start {start} > end {end}")
        if start == end:
            continue
        cleaned.append((start, end))

    if not cleaned:
        return []

    cleaned.sort(key=lambda pair: (pair[0], pair[1]))

    merged: List[Tuple[int, int]] = [cleaned[0]]
    for start, end in cleaned[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged"}}, "messages": []}

